SET enable_profile=true; SET auto_profile_threshold_ms=0; USE doris_book; EXPLAIN SELECT city,revenue FROM (SELECT city,amount AS revenue FROM orders_intro_v1)t WHERE revenue>100; SELECT city,revenue FROM (SELECT city,amount AS revenue FROM orders_intro_v1)t WHERE revenue>100 ORDER BY revenue; EXPLAIN SELECT order_id,revenue FROM (SELECT order_id,amount AS revenue FROM orders_intro_v1 ORDER BY order_id LIMIT 2)t WHERE revenue>100; SELECT COUNT(*) FROM (SELECT order_id,amount AS revenue FROM orders_intro_v1 ORDER BY order_id LIMIT 2)t WHERE revenue>100;
